import React from "react";

export default function Progress() {

  return (

    <div
      style={{

        minHeight: "100vh",

        background: "#f1f5f9",

        padding: "40px"

      }}
    >

      <h1
        style={{

          textAlign: "center",

          color: "#1e293b",

          fontSize: "45px",

          marginBottom: "10px"

        }}
      >

        📈 Progress Dashboard

      </h1>

      <p
        style={{

          textAlign: "center",

          color: "gray",

          marginBottom: "40px"

        }}
      >

        Track Your Learning Progress

      </p>


      <div

        style={{

          display: "grid",

          gridTemplateColumns:

            "repeat(auto-fit,minmax(250px,1fr))",

          gap: "25px"

        }}

      >

        <div style={blueCard}>

          <h2>📚 Courses</h2>

          <h1>8</h1>

          <p>Completed Courses</p>

        </div>


        <div style={greenCard}>

          <h2>🏆 Score</h2>

          <h1>92%</h1>

          <p>Overall Performance</p>

        </div>


        <div style={orangeCard}>

          <h2>🔥 Attendance</h2>

          <h1>96%</h1>

          <p>Current Attendance</p>

        </div>


        <div style={pinkCard}>

          <h2>⭐ Skills</h2>

          <h1>15</h1>

          <p>Skills Learned</p>

        </div>

      </div>


      <div

        style={{

          background: "white",

          marginTop: "50px",

          padding: "30px",

          borderRadius: "20px",

          boxShadow:

            "0 10px 25px rgba(0,0,0,0.1)"

        }}

      >

        <h2

          style={{

            color: "#2563eb",

            marginBottom: "25px"

          }}

        >

          Course Progress

        </h2>


        <h3>Java Full Stack</h3>

        <progress

          value="85"

          max="100"

          style={{

            width: "100%",

            height: "25px"

          }}

        />

        <p>85%</p>


        <h3>React JS</h3>

        <progress

          value="70"

          max="100"

          style={{

            width: "100%",

            height: "25px"

          }}

        />

        <p>70%</p>


        <h3>Python Programming</h3>

        <progress

          value="90"

          max="100"

          style={{

            width: "100%",

            height: "25px"

          }}

        />

        <p>90%</p>

      </div>

    </div>

  );

}



const blueCard = {

  background: "#2563eb",

  color: "white",

  padding: "30px",

  borderRadius: "20px",

  textAlign: "center"

};


const greenCard = {

  background: "#16a34a",

  color: "white",

  padding: "30px",

  borderRadius: "20px",

  textAlign: "center"

};


const orangeCard = {

  background: "#f59e0b",

  color: "white",

  padding: "30px",

  borderRadius: "20px",

  textAlign: "center"

};


const pinkCard = {

  background: "#ec4899",

  color: "white",

  padding: "30px",

  borderRadius: "20px",

  textAlign: "center"

};
